INSERT INTO family_tree (clan_id, json, json_ko) VALUES ('c11c-b2ec-c131', '{"clanId":"c11c-b2ec-c131","personId":null,"nodes":[{"id":"K149","personId":"K149","kind":"person","name":"Seo Ra-on","birthDate":"2080-06-20","deathDate":null,"status":"preserved","sourceRefs":[{"path":"docs/drafts/people/government.jsonl","anchor":"person-0150"}],"timeline":[{"year":2126,"summary":"On one desk in the Bomun Station district office the duty roster of the watchtowers facing the Bukhansan edge and the quota papers of the school on the old university grounds arrive together, and the Member of the National Assembly for Seongbuk-gu, a head of household of the Dalseong Seo, approves both."}],"detailRoute":"/people/person-0150","affiliation":{"kind":"state","stateId":"government","name":"The Government"}},{"id":"K198","personId":"K198","kind":"person","name":"Seo Na-yeon","birthDate":"2064-03-14","deathDate":null,"status":"preserved","sourceRefs":[{"path":"docs/drafts/people/government.jsonl","anchor":"person-0199"}],"timeline":[{"year":2126,"summary":"Seo Na-yeon, heir of the Seongbuk-gu Assembly house, is of the Dalseong Seo and sixty-two, and she is registered on the deep level of Bomun Station."}],"detailRoute":"/people/person-0199","affiliation":{"kind":"state","stateId":"government","name":"The Government"}},{"id":"K274","personId":"K274","kind":"person","name":"Seo Jin-a","birthDate":"2092-02-08","deathDate":null,"status":"preserved","sourceRefs":[{"path":"docs/drafts/people/arc.jsonl","anchor":"person-0275"}],"timeline":[{"year":2126,"summary":"Seo Jin-a, the thirty-four-year-old Shelter Head of Seocho 4-dong, begins each day on the concourse level of Gangnam Station by counting how many names answered at the first-shift Calling."}],"detailRoute":"/people/person-0275","affiliation":{"kind":"state","stateId":"arc","name":"Arc"}},{"id":"K321","personId":"K321","kind":"person","name":"Seo Ongyeol","birthDate":"2089-10-18","deathDate":null,"status":"preserved","sourceRefs":[{"p